/// Blocks above U+10FF that hold narrow letters but stay at the default
/// weight under v4 as well: Korean, logographic scripts, and letter-shaped
/// symbols.
#[test]
fn excluded_blocks_keep_the_default_weight() {
    let v4 = config_v4();
    let excluded: &[(&str, i32, i32, &str)] = &[
        ("Superscripts and Subscripts", 0x2070, 0x209F, "\u{2071}"),
        (
            "Combining Diacritical Marks for Symbols",
            0x20D0,
            0x20FF,
            "\u{20D0}",
        ),
        ("Letterlike Symbols", 0x2100, 0x214F, "\u{2102}"),
        ("Number Forms", 0x2150, 0x218F, "\u{2183}"),
        ("Supplemental Punctuation", 0x2E00, 0x2E7F, "\u{2E2F}"),
        ("Hangul Jamo Extended-B", 0xD7B0, 0xD7FF, "\u{D7B0}"),
        ("Variation Selectors", 0xFE00, 0xFE0F, "\u{FE00}"),
        ("Linear B Ideograms", 0x10080, 0x100FF, "\u{10080}"),
        ("Phaistos Disc", 0x101D0, 0x101FF, "\u{101FD}"),
        ("Coptic Epact Numbers", 0x102E0, 0x102FF, "\u{102E0}"),
        ("Linear A", 0x10600, 0x1077F, "\u{10600}"),
        ("Cuneiform", 0x12000, 0x123FF, "\u{12000}"),
        ("Early Dynastic Cuneiform", 0x12480, 0x1254F, "\u{12480}"),
        ("Cypro-Minoan", 0x12F90, 0x12FFF, "\u{12F90}"),
        ("Egyptian Hieroglyphs", 0x13000, 0x1342F, "\u{13000}"),
        (
            "Egyptian Hieroglyph Format Controls",
            0x13430,
            0x1345F,
            "\u{13441}",
        ),
        (
            "Egyptian Hieroglyphs Extended-A",
            0x13460,
            0x143FF,
            "\u{13460}",
        ),
        ("Anatolian Hieroglyphs", 0x14400, 0x1467F, "\u{14400}"),
        ("Znamenny Musical Notation", 0x1CF00, 0x1CFCF, "\u{1CF00}"),
        ("Musical Symbols", 0x1D100, 0x1D1FF, "\u{1D127}"),
        (
            "Ancient Greek Musical Notation",
            0x1D200,
            0x1D24F,
            "\u{1D242}",
        ),
        ("Musical Symbols Supplement", 0x1D250, 0x1D28F, "\u{1D250}"),
        (
            "Mathematical Alphanumeric Symbols",
            0x1D400,
            0x1D7FF,
            "\u{1D400}",
        ),
        ("Sutton SignWriting", 0x1D800, 0x1DAAF, "\u{1DA00}"),
        (
            "Arabic Mathematical Alphabetic Symbols",
            0x1EE00,
            0x1EEFF,
            "\u{1EE00}",
        ),
        (
            "Variation Selectors Supplement",
            0xE0100,
            0xE01EF,
            "\u{E0100}",
        ),
    ];
    for (name, start, end, sample) in excluded {
        assert!(
            !v4.ranges
                .iter()
                .any(|r| r.contains(*start) || r.contains(*end)),
            "{} U+{:04X}..U+{:04X} should not be in any v4 range",
            name,
            start,
            end
        );
        assert_eq!(
            weighted_length(v4, sample),
            2,
            "{}: {:?} should weigh two units under v4",
            name,
            sample
        );
    }
}

/// v4 is v3 plus the alphabetic blocks: every v3 range appears in v4 verbatim.
#[test]
fn v4_is_a_superset_of_v3() {
    let v4 = config_v4();
    let v3 = config_v3();
    assert_eq!(v4.version, 4);
    assert_eq!(v3.version, 3);
    for range in &v3.ranges {
        assert!(
            v4.ranges.contains(range),
            "v3 range {:?} is missing from v4",
            range
        );
    }
    assert_eq!(v4.max_weighted_tweet_length, v3.max_weighted_tweet_length);
    assert_eq!(v4.scale, v3.scale);
    assert_eq!(v4.default_weight, v3.default_weight);
    assert_eq!(v4.transformed_url_length, v3.transformed_url_length);
    assert_eq!(v4.emoji_parsing_enabled, v3.emoji_parsing_enabled);
}

/// The ranges are sorted and disjoint, so the first range that contains a
/// code point is the only one that does.
#[test]
fn v4_ranges_are_sorted_and_disjoint() {
    let ranges = &config_v4().ranges;
    assert_eq!(ranges.len(), 52);
    for pair in ranges.windows(2) {
        assert!(
            pair[0].range.end() < pair[1].range.start(),
            "{:?} overlaps or follows {:?}",
            pair[0],
            pair[1]
        );
    }
}
